//KODE DI FRAME 1 : Actions
import flash.display.StageScaleMode;
import flash.display.StageAlign;
import flash.events.Event;

// 1. Hentikan timeline agar tidak auto-play
stop();

// 2. Atur alignment (perataan) ke pojok kiri atas
stage.align = StageAlign.TOP_LEFT;

// 3. Atur scale mode (mode skala)
// Ini kode yang membuat 1920x1080 pas di semua layar
stage.scaleMode = StageScaleMode.NO_BORDER;

//KODE DI FRAME 1 : Actions

// 1. Hentikan timeline agar tidak auto-play
//stop();

// 2. Atur alignment (perataan) ke pojok kiri atas
stage.align = StageAlign.TOP_LEFT;

// 3. Atur scale mode (mode skala)
// Ini kode yang membuat 1920x1080 pas di semua layar
stage.scaleMode = StageScaleMode.NO_BORDER;

//KODE DI FRAME 1 : Actions

// 1. Hentikan timeline agar tidak auto-play
//stop();

// 2. Atur alignment (perataan) ke pojok kiri atas
//stage.align = StageAlign.TOP_LEFT;

// 3. Atur scale mode (mode skala)
// Ini kode yang membuat 1920x1080 pas di semua layar
//stage.scaleMode = StageScaleMode.SHOW_ALL;

// 1. Fungsi untuk memaksa layar tetap rapi
function aturLayar(e:Event = null):void {
    stage.scaleMode = StageScaleMode.SHOW_ALL; // Pastikan semua terlihat
    stage.align = StageAlign.TOP_LEFT; // Kunci di pojok kiri atas
}

// 2. Jalankan fungsi ini SEKARANG
aturLayar();

// 3. Jalankan fungsi ini SETIAP KALI layar berubah (misal HP diputar)
stage.addEventListener(Event.ENTER_FRAME, aturLayar);
